{
  "api": "/api/startup/stats",
  "description": "Retrieves key performance indicators for a specific startup, such as funding rounds, employee count, revenue, and valuation over time.",
  "parameters": {
    "company_id": {
      "type": "string",
      "required": true,
      "description": "Unique identifier for the startup."
    },
    "start_date": {
      "type": "string",
      "format": "date",
      "required": false,
      "description": "ISO‑8601 start date for the statistics period (inclusive). Defaults to 12 months prior to end_date."
    },
    "end_date": {
      "type": "string",
      "format": "date",
      "required": false,
      "description": "ISO‑8601 end date for the statistics period (inclusive). Defaults to today."
    },
    "metrics": {
      "type": "array",
      "items": {
        "type": "string",
        "enum": ["funding", "employees", "revenue", "valuation", "burn_rate"]
      },
      "required": false,
      "description": "Specific metrics to return. If omitted, all available metrics are returned."
    }
  },
  "response": {
    "type": "object",
    "properties": {
      "company_id": { "type": "string" },
      "company_name": { "type": "string" },
      "statistics": {
        "type": "array",
        "items": {
          "type": "object",
          "properties": {
            "date": { "type": "string", "format": "date" },
            "funding": { "type": "number", "description": "Total funding raised up to this date (USD)" },
            "employees": { "type": "integer", "description": "Number of employees on this date" },
            "revenue": { "type": "number", "description": "Revenue for the month (USD)" },
            "valuation": { "type": "number", "description": "Company valuation at this date (USD)" },
            "burn_rate": { "type": "number", "description": "Monthly cash burn rate (USD)" }
          },
          "required": ["date"]
        }
      }
    },
    "required": ["company_id", "company_name", "statistics"]
  },
  "examples": [
    {
      "request": {
        "method": "GET",
        "url": "/api/startup/stats?company_id=abc123&start_date=2023-01-01&end_date=2023-12-31&metrics=funding,revenue"
      },
      "response": {
        "company_id": "abc123",
        "company_name": "TechNova Inc.",
        "statistics": [
          { "date": "2023-01-01", "funding": 5000000, "revenue": 200000 },
